  def self.apply_map_tone
    return if !$game_map || !$game_screen
    t = MAP_TONES[$game_map.map_id]
    tone = (t) ? Tone.new(*t) : Tone.new(0, 0, 0, 0)
    return if @last_tone_map == $game_map.map_id
    @last_tone_map = $game_map.map_id
    $game_screen.start_tone_change(tone, 0) if t || @tone_was_set
    @tone_was_set = !t.nil?
